// gen-third-party-notices.mjs — regenerate ../../THIRD_PARTY_NOTICES.md from the
// installed npm dependency trees. Run from the plugin root:
//   node Source/ThirdParty/gen-third-party-notices.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const pluginRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const roots = [
  path.join(pluginRoot, "Source/ThirdParty/unrealngg-mcp/node_modules"),
  path.join(pluginRoot, "Source/ThirdParty/ngg-sidecar/node_modules"),
];
const seen = new Map();

function walk(dir) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    if (!e.isDirectory() || e.name === ".bin") continue;
    const full = path.join(dir, e.name);
    if (e.name.startsWith("@")) { walk(full); continue; }
    const pj = path.join(full, "package.json");
    if (fs.existsSync(pj)) {
      try {
        const p = JSON.parse(fs.readFileSync(pj, "utf8"));
        if (p.name) seen.set(p.name, { v: p.version || "", l: p.license || "UNKNOWN" });
      } catch {}
    }
    const nm = path.join(full, "node_modules");
    if (fs.existsSync(nm)) walk(nm);
  }
}
roots.forEach(walk);

const arr = [...seen.entries()].sort((a, b) => a[0].localeCompare(b[0]));
const byLic = {};
for (const [, o] of arr) byLic[o.l] = (byLic[o.l] || 0) + 1;

const L = [];
L.push("# Third-Party Software Notices");
L.push("");
L.push("The UnrealNGGMCP plugin and its first-party tooling (the C++ module under");
L.push("`Source/`, and the `Source/ThirdParty/unrealngg-mcp`, `Source/ThirdParty/ngg-sidecar`, and");
L.push("`Content/Python/bp-extract` sources) are proprietary, distributed under the Fab");
L.push("license — © NGG, All Rights Reserved. The notices below cover only the");
L.push("**third-party** dependencies those tools rely on.");
L.push("");
L.push("This plugin ships the **source** of two Node.js helper tools (`Source/ThirdParty/unrealngg-mcp`");
L.push("and `Source/ThirdParty/ngg-sidecar`). Their npm dependencies are **not** vendored in the");
L.push("packaged plugin — end users install them with `npm install`, which fetches the");
L.push("exact versions pinned in each `package-lock.json`. The packages below are listed");
L.push("for attribution; each is distributed under its own permissive license by its");
L.push("respective authors.");
L.push("");
L.push("The `Content/Python/bp-extract` tool is pure Python using only the standard library and");
L.push("has no third-party dependencies.");
L.push("");
L.push("## License summary");
L.push("");
L.push("| License | Packages |");
L.push("|---|---|");
for (const k of Object.keys(byLic).sort()) L.push(`| ${k} | ${byLic[k]} |`);
L.push("");
L.push(`**Total: ${arr.length} packages, all permissive (MIT / ISC / BSD).**`);
L.push("");
L.push("Full license text for each package is included in that package directory under");
L.push("`node_modules/<pkg>/LICENSE` after `npm install`.");
L.push("");
L.push("## Direct dependencies");
L.push("");
L.push("- **unrealngg-mcp**: `@modelcontextprotocol/sdk` (MIT), `zod` (MIT), `youtube-transcript` (MIT)");
L.push("- **ngg-sidecar**: `ws` (MIT)");
L.push("");
L.push("## All packages (direct + transitive)");
L.push("");
L.push("| Package | Version | License |");
L.push("|---|---|---|");
for (const [n, o] of arr) L.push(`| \`${n}\` | ${o.v} | ${o.l} |`);
L.push("");
L.push("---");
L.push("");
L.push("Generated by `Source/ThirdParty/gen-third-party-notices.mjs`. Re-run after changing");
L.push("dependencies to keep this file accurate.");
L.push("");

fs.writeFileSync(path.join(pluginRoot, "THIRD_PARTY_NOTICES.md"), L.join("\n"));
console.log(`Wrote THIRD_PARTY_NOTICES.md (${arr.length} packages)`);
